package com.nigson.experience.consent;

import java.net.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import static org.assertj.core.api.Assertions.*;

class NewsletterPersistenceTest {
 static final String POLICY="SYNTHETIC_POLICY";
 JdbcTemplate jdbc;NewsletterService service;ConsentSecrets secrets;DataSourceTransactionManager manager;Clock clock=Clock.systemUTC();
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"consent persistence scenarios run through scripts/consent/verify.py");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();var store=new PlatformStore(jdbc,manager,clock,metrics);var audit=new AuditWriter(jdbc,clock,metrics);byte[] hash=new byte[32],cipher=new byte[32];Arrays.fill(hash,(byte)5);Arrays.fill(cipher,(byte)9);secrets=new ConsentSecrets(1,hash,"synthetic",Map.of("synthetic",cipher));service=new NewsletterService(jdbc,store,audit,secrets,manager,clock,POLICY,Set.of(POLICY),"https://newsletter.example.invalid",(token,key)->"synthetic-anti-spam".equals(token));}
 private NewsletterService.Accepted subscribe(String email,String key){return service.subscribe(new NewsletterService.Request(email,POLICY,"synthetic-anti-spam"),key,UUID.randomUUID());}
 private PrivateWorkload.Proof proof(String api,ActorAssertion.Actor actor){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,actor);}
 private String token(String link){try{return URLDecoder.decode(URI.create(link).getRawQuery().substring("token=".length()),StandardCharsets.UTF_8);}catch(Exception failure){throw new AssertionError(failure);}}
 private UUID subscription(String email){return jdbc.queryForObject("SELECT id FROM experience.newsletter_subscription WHERE email_hash=?",UUID.class,secrets.emailHash(email));}
 @Test void doubleOptInBindsStableNotificationContextAndUnsubscribeSuppressesAtomically(){String email="newsletter@example.invalid";String key=UUID.randomUUID().toString();assertThat(subscribe(email,key).accepted()).isTrue();UUID id=subscription(email);assertThat(jdbc.queryForObject("SELECT state FROM experience.newsletter_subscription WHERE id=?",String.class,id)).isEqualTo("PENDING");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE destination_hash=?",Long.class,secrets.emailHash(email))).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='newsletter.verification.requested.v1'",Long.class,id)).isEqualTo(1);
  var integration=proof("API-158",null);UUID job=UUID.randomUUID();var first=service.context(integration,id,job,UUID.randomUUID());var retry=service.context(integration,id,job,UUID.randomUUID());assertThat(first).isEqualTo(retry);assertThat(first.email()).isEqualTo(email);assertThat(first.confirmationLink()).startsWith("https://newsletter.example.invalid/newsletter/confirm?");assertThat(first.unsubscribeLink()).startsWith("https://newsletter.example.invalid/newsletter/unsubscribe?");assertThatThrownBy(()->service.context(integration,id,UUID.randomUUID(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.ACCESS_DENIED);
  byte[] context=jdbc.queryForObject("SELECT encrypted_confirmation_context FROM experience.newsletter_subscription WHERE id=?",byte[].class,id);assertThat(new String(context,StandardCharsets.US_ASCII)).doesNotContain(email,token(first.confirmationLink()),token(first.unsubscribeLink()));var confirmed=service.confirm(token(first.confirmationLink()),UUID.randomUUID().toString(),UUID.randomUUID());assertThat(confirmed.confirmed()).isTrue();assertThat(service.confirm(token(first.confirmationLink()),UUID.randomUUID().toString(),UUID.randomUUID()).confirmed()).isFalse();assertThat(jdbc.queryForObject("SELECT state FROM experience.newsletter_subscription WHERE id=?",String.class,id)).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE destination_hash=? AND channel='EMAIL' AND purpose='NEWSLETTER' AND granted",Long.class,secrets.emailHash(email))).isEqualTo(1);
  assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.newsletter_subscription WHERE id=? AND state='ACTIVE' AND rtrim(email_hash)=?",Long.class,id,secrets.emailHash(email))).isEqualTo(1);var emailInput=new PhoneValues.EligibilityInput(null,id,"EMAIL","NEWSLETTER");var eligibility=service.emailEligibility(proof("API-127",null),emailInput,UUID.randomUUID());assertThat(eligibility.eligible()).isTrue();assertThat(eligibility.email()).isEqualTo(email);
  var activeContext=service.context(integration,id,job,UUID.randomUUID());assertThat(activeContext.confirmationLink()).isNull();assertThat(activeContext.unsubscribeLink()).isEqualTo(first.unsubscribeLink());String unsubscribeKey=UUID.randomUUID().toString();assertThat(service.unsubscribe(token(first.unsubscribeLink()),unsubscribeKey,UUID.randomUUID()).unsubscribed()).isTrue();assertThat(service.unsubscribe(token(first.unsubscribeLink()),unsubscribeKey,UUID.randomUUID()).unsubscribed()).isTrue();assertThat(jdbc.queryForObject("SELECT state FROM experience.newsletter_subscription WHERE id=?",String.class,id)).isEqualTo("UNSUBSCRIBED");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL' AND reason='WITHDRAWN'",Long.class,secrets.emailHash(email))).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.consent_event WHERE destination_hash=? AND channel='EMAIL' AND purpose='NEWSLETTER' AND NOT granted",Long.class,secrets.emailHash(email))).isEqualTo(1);var denied=service.emailEligibility(proof("API-127",null),emailInput,UUID.randomUUID());assertThat(denied.eligible()).isFalse();assertThat(denied.email()).isNull();assertThat(denied.reasonCode()).isEqualTo("SUPPRESSED");
  assertThat(subscribe(email,UUID.randomUUID().toString()).accepted()).isTrue();assertThat(jdbc.queryForObject("SELECT state FROM experience.newsletter_subscription WHERE id=?",String.class,id)).isEqualTo("PENDING");var fresh=service.context(integration,id,UUID.randomUUID(),UUID.randomUUID());assertThat(service.emailEligibility(proof("API-127",null),emailInput,UUID.randomUUID()).eligible()).isFalse();assertThat(service.confirm(token(fresh.confirmationLink()),UUID.randomUUID().toString(),UUID.randomUUID()).confirmed()).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL'",Long.class,secrets.emailHash(email))).isZero();
  for(String wire:jdbc.queryForList("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=?",String.class,id)){assertThat(wire).doesNotContain(email,token(first.confirmationLink()),token(first.unsubscribeLink()));EventCodec.decode(wire);} }
 @Test void api102RequiresOwnedSignedCustomerAndCurrentVersionAndWritesPurposeSuppression(){String email="owned@example.invalid";subscribe(email,UUID.randomUUID().toString());UUID id=subscription(email);var context=service.context(proof("API-158",null),id,UUID.randomUUID(),UUID.randomUUID());assertThat(service.confirm(token(context.confirmationLink()),UUID.randomUUID().toString(),UUID.randomUUID()).confirmed()).isTrue();UUID party=UUID.randomUUID();jdbc.update("UPDATE experience.newsletter_subscription SET party_id=? WHERE id=?",party,id);long current=jdbc.queryForObject("SELECT version FROM experience.newsletter_subscription WHERE id=?",Long.class,id);var actor=new ActorAssertion.Actor(party,"http://synthetic.invalid","customer",null,Set.of("CUSTOMER"),Set.of("consent.write_WITH_SIGNED_CUSTOMER"),null);var proof=proof("API-102",actor);var input=new NewsletterService.SetConsentInput(id,"EMAIL","MARKETING",true,POLICY);var granted=service.setEmailConsent(proof,input,current,UUID.randomUUID().toString(),UUID.randomUUID());assertThat(granted.granted()).isTrue();assertThatThrownBy(()->service.setEmailConsent(proof,input,current,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.VERSION_MISMATCH);var withdrawn=service.setEmailConsent(proof,new NewsletterService.SetConsentInput(id,"EMAIL","MARKETING",false,POLICY),current+1,UUID.randomUUID().toString(),UUID.randomUUID());assertThat(withdrawn.granted()).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=? AND channel='EMAIL'",Long.class,secrets.emailHash(email))).isEqualTo(1);var denied=service.emailEligibility(proof("API-127",null),new PhoneValues.EligibilityInput(null,id,"EMAIL","MARKETING"),UUID.randomUUID());assertThat(denied.eligible()).isFalse();assertThatThrownBy(()->service.setEmailConsent(proof("API-102",new ActorAssertion.Actor(UUID.randomUUID(),"http://synthetic.invalid","outsider",null,Set.of("CUSTOMER"),Set.of("consent.write_WITH_SIGNED_CUSTOMER"),null)),input,current+2,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.NOT_FOUND);}
}
